                "wikall_snapshot_api_pending" => "wikall_snapshot_api_pending",
                "wikall_snapshot_peer_query" => "wikall_snapshot_peer_query",
                "wikall_snapshot_node_query" => "wikall_snapshot_node_query",
                "wikall_snapshot_route_query" => "wikall_snapshot_route_query",
                "wikall_snapshot_portal_query" => "wikall_snapshot_portal_query",
                "wikall_snapshot_foreign_query" => "wikall_snapshot_foreign_query",
                _ => "wikall_snapshot_unavailable",
            }
        } else {
            match instance.get_latest_error_msg() {
                Some(message) => {
                    let lower = message.to_ascii_lowercase();
                    if lower.contains("permission denied") || lower.contains("operation not permitted") {
                        "wikall_stopped_permission_denied"
                    } else if lower.contains("address already in use") {
                        "wikall_stopped_address_in_use"
                    } else if lower.contains("network is unreachable") || lower.contains("no route to host") {
                        "wikall_stopped_network_unreachable"
                    } else {
                        "wikall_stopped_other"
                    }
                }
                None => "wikall_stopped_no_detail",
            }
        };
        ret.insert(*instance.key(), NetworkInstanceRunningInfo {
            running,
            error_msg: Some(category.to_owned()),
            ..Default::default()
        });
    }
}

